import sys
import json
import subprocess
import os

def main():
    if len(sys.argv) < 3:
        print("Usage: python batch_runner.py <output_json_file> <log_file>", file=sys.stderr)
        sys.exit(1)

    output_json = sys.argv[1]
    log_file = sys.argv[2]

    try:
        with open(log_file, 'a') as f:
            f.write("Finished\n")
    except IOError as e:
        print(f"Error: {str(e)}", file=sys.stderr)
        sys.exit(1)

    results = []
    command_lines = []
    try:
        for line in sys.stdin:
            stripped_line = line.strip()
            if stripped_line:
                command_lines.append(stripped_line)
    except IOError as e:
        print(f"Error: {str(e)}", file=sys.stderr)
        sys.exit(1)

    for cmd in command_lines:
        try:
            result = subprocess.run(cmd, shell=True, check=False, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
            exit_code = result.returncode
            stdout = result.stdout.strip()
            stderr = result.stderr.strip()
        except Exception as e:
            exit_code = -1
            stderr = str(e)
            stdout = ""

        results.append({
            "command": cmd,
            "exit_code": exit_code,
            "stdout": stdout,
            "stderr": stderr
        })

        try:
            with open(log_file, 'a') as f:
                f.write(f"{cmd}\t{exit_code}\t{len(stdout)}\n")
        except IOError as e:
            print(f"Error: {str(e)}", file=sys.stderr)
            sys.exit(1)

    try:
        with open(output_json, 'w') as f:
            json.dump(results, f, indent=2)
    except IOError as e:
        print(f"Error: {str(e)}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()
